head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : 기본 옵션(fileName, delim, header) + options 파라미터 공통 / @spec. description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > saveCSV]<br/>GridView 컴포넌트의 데이터를 CSV 형식의 파일로 다운로드합니다.",
    "validation" : [
        "JDK 1.5 이상에서 사용할 수 있으며 GridView 에 DataList 가 바인딩 되어 있어야 합니다.",
        "options(필수) 파라미터로 CSV 데이터 다운로드 옵션을 객체로 설정합니다.",
        "다운로드 옵션을 기본값으로만 설정할 경우 빈 객체({})로 설정해야 합니다.",
        "fileName(선택) 파라미터로 다운로드될 CSV 파일명을 설정합니다.",
        "fileName(선택) 파라미터의 확장자 생략 시 'csv' 가 설정됩니다.",
        "fileName(선택) 파라미터를 생략하면 기본값 'csvfile.csv' 로 동작합니다.",
        "delim(선택) 파라미터로 CSV 데이터의 Column 을 구분하는 문자를 설정합니다.",
        "delim(선택) 파라미터를 생략하면 기본값 ';' 로 동작합니다.",
        "header(선택) 파라미터로 GridView 의 Header 값 포함 여부를 설정합니다.",
        "header(선택) 파라미터를 '0' 으로 설정 시 Header 값을 제외하고 다운로드합니다.",
        "header(선택) 파라미터를 '1' 로 설정 시 Header 값을 포함하여 다운로드합니다.",
        "header(선택) 파라미터를 생략하면 기본값 '1' 로 동작합니다.",
        "CSV 데이터의 Column 을 구분하는 문자의 기본값이 saveCSV() 메소드는 ';' 이고, readCSV() 메소드는 ',' 이므로 주의하여야 합니다.",
        "readCSV() 메소드의 기본 서블릿은 'csvToXML.wq' 이고, saveCSV() 메소드의 기본 서블릿은 'xmlToCSV.wq' 입니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · saveCSV 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n[절차]\n1. par 옵션(fileName / delim / header) 값을 선택한다\n2. saveCSV 버튼을 클릭하여 CSV 파일을 다운로드한다\n3. (다운로드와 무관) 기본서블릿확인 버튼을 클릭한다\n[확인]\n- 2번 직후 결과창에 실제 전달된 options 객체가 출력됨 (미설정 옵션은 객체에 담기지 않고 생략됨)\n- 다운로드된 파일의 이름으로 fileName 반영 여부를 확인 (확장자 생략 값 선택 시 csv 가 붙는지 확인)\n- 다운로드된 파일을 텍스트로 열어 Column 구분 문자(delim)와 Header 행(name1 ~ name4) 포함 여부를 확인\n- 3번 출력에서 saveCSV / readCSV 의 기본 서블릿 경로를 확인"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 saveCSV options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 모든 파라미터가 미설정이면 빈 객체({}) 가 전달된다.
scwin.buildOptions = function () {
    let options = {};
    let v;

    v = par_fileName.getValue();
    if (v !== "") options.fileName = v;

    v = par_delim.getValue();
    if (v !== "") options.delim = v;

    v = par_header.getValue();
    if (v !== "") options.header = v;

    return options;
}



// saveCSV 실행
//  · 실제 전달되는 options 객체를 출력하여 미설정 파라미터가 생략되었음을 확인한다.
//  · 파일명 / 구분 문자 / Header 행 포함 여부는 다운로드된 CSV 파일에서 확인한다.
scwin.btn_saveCSV_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let options = scwin.buildOptions();
    bottom.setReturnValue("전달 options : " + JSON.stringify(options));

    target1.saveCSV(options);
}



// 기본 서블릿 경로 확인 (@spec)
scwin.btn_getServletURL_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("saveCSV 기본 서블릿 : " + target1.options.csvDownloadURL + " / readCSV 기본 서블릿 : " + target1.options.csvUploadURL);
}
